.md-field {
  display: flex;
  flex-direction: column;
  gap: var(--g-spacing-2);
  min-width: 0;
}

.md-field__label {
  cursor: pointer;
}

.md-field__panes {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: var(--g-spacing-3);
  align-items: stretch;
}

.md-field__panes textarea {
  font-family: var(--g-font-family-monospace);
  font-size: 14px;
  line-height: 1.5;
}

.md-field__preview {
  min-width: 0;
  padding: var(--g-spacing-3) var(--g-spacing-4);
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-m);
  background: var(--g-color-base-background);
  overflow-wrap: anywhere;
}

@media (max-width: 760px) {
  .md-field__panes {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* Оформление отрендеренного markdown. Цвета берём из темы Gravity UI. */
.md-preview {
  color: var(--g-color-text-primary);
  font-family: var(--g-font-family-sans);
  font-size: 15px;
  line-height: 1.6;
}

.md-preview > :first-child {
  margin-top: 0;
}

.md-preview > :last-child {
  margin-bottom: 0;
}

.md-preview h1,
.md-preview h2,
.md-preview h3,
.md-preview h4,
.md-preview h5,
.md-preview h6 {
  margin: 1.2em 0 0.5em;
  line-height: 1.25;
  font-weight: 600;
}

.md-preview h1 {
  font-size: 1.8em;
}

.md-preview h2 {
  font-size: 1.45em;
}

.md-preview h3 {
  font-size: 1.2em;
}

.md-preview p,
.md-preview ul,
.md-preview ol,
.md-preview blockquote,
.md-preview pre,
.md-preview table {
  margin: 0 0 0.9em;
}

.md-preview ul,
.md-preview ol {
  padding-left: 1.5em;
}

.md-preview li + li {
  margin-top: 0.25em;
}

.md-preview blockquote {
  padding: 0 1em;
  border-left: 3px solid var(--g-color-line-generic-accent);
  color: var(--g-color-text-secondary);
}

.md-preview code {
  padding: 0.1em 0.35em;
  border-radius: var(--g-border-radius-xs);
  background: var(--g-color-base-generic);
  font-family: var(--g-font-family-monospace);
  font-size: 0.9em;
}

.md-preview pre {
  padding: var(--g-spacing-3);
  border-radius: var(--g-border-radius-m);
  background: var(--g-color-base-generic);
  overflow-x: auto;
}

.md-preview pre code {
  padding: 0;
  background: none;
}

.md-preview a {
  color: var(--g-color-text-brand);
}

.md-preview img {
  max-width: 100%;
}

.md-preview hr {
  margin: 1.2em 0;
  border: none;
  border-top: 1px solid var(--g-color-line-generic);
}

.md-preview table {
  border-collapse: collapse;
  display: block;
  overflow-x: auto;
}

.md-preview th,
.md-preview td {
  padding: 0.35em 0.7em;
  border: 1px solid var(--g-color-line-generic);
  text-align: left;
}

