import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('dialog', (d) => { errors.push('DIALOG: ' + d.message()); d.dismiss(); });

await page.goto('http://localhost:5199/', { waitUntil: 'networkidle' });
const textarea = page.locator('textarea[name="body"]');
await textarea.waitFor();

const preview = page.locator('.md-field__preview');
console.log('empty preview:', (await preview.innerText()).trim());

const md = '# Большой заголовок\n\n**жирный** и *курсив* и `код`\n\n- первый\n- второй\n\n> цитата\n\n[ссылка](https://example.com)\n\n<img src=x onerror="alert(1)">\n\n<script>alert(2)</script>\n\n| a | b |\n|---|---|\n| 1 | 2 |';
await textarea.fill(md);
await page.waitForTimeout(300);

const html = await preview.locator('.md-preview').innerHTML();
const checks = {
  h1: await preview.locator('.md-preview h1').count(),
  strong: await preview.locator('.md-preview strong').count(),
  em: await preview.locator('.md-preview em').count(),
  code: await preview.locator('.md-preview code').count(),
  li: await preview.locator('.md-preview li').count(),
  blockquote: await preview.locator('.md-preview blockquote').count(),
  table: await preview.locator('.md-preview table').count(),
  linkTargetBlank: await preview.locator('.md-preview a[target="_blank"][rel="noopener noreferrer"]').count(),
  scriptTag: await preview.locator('.md-preview script').count(),
  onerrorAttr: html.includes('onerror'),
};
console.log('preview checks:', JSON.stringify(checks));

await page.screenshot({ path: '/tmp/pwcheck/editing.png', fullPage: true });

await page.locator('input[name="title"]').fill('Тестовая статья');
await page.getByRole('button', { name: 'Отправить' }).click();
await page.waitForTimeout(300);
const card = page.locator('h2', { hasText: 'Тестовая статья' });
console.log('submitted card title shown:', await card.count());
console.log('submitted card h1 count:', await page.locator('h1', { hasText: 'Большой заголовок' }).count());
await page.screenshot({ path: '/tmp/pwcheck/submitted.png', fullPage: true });

await page.setViewportSize({ width: 500, height: 900 });
await page.waitForTimeout(200);
const panes = await page.locator('.md-field__panes').evaluate((el) => getComputedStyle(el).gridTemplateColumns);
console.log('narrow grid columns:', panes);

console.log('errors:', JSON.stringify(errors));
await browser.close();
EOF
cd /tmp/pwcheck && timeout 120 node check.mjs

